  var cfg = {
    open: body.open === true,
    fields: fields,
    photo: { enabled: ph.enabled === true, required: ph.enabled === true && ph.required === true },
    aadhaarPhoto: { front: side(ap.front, 'Aadhaar Front Photo'), back: side(ap.back, 'Aadhaar Back Photo') },
    regNo: { next: regNext },
    mail: { student: mi.student === true, admin: mi.admin === true && adminEmails.length > 0, adminEmail: adminEmails.join(',') },
    idCard: body.idCard ? IDC_.normalize(body.idCard) : null,   // CMS: Settings -> ID Card
    options: { categories: cats, batches: batches, locations: locs }
  };
