      '<path d="M0,347 L58,396" stroke="' + T.a1 + '" stroke-width="1" fill="none"/>' +
      '<path d="M255,344 L255,404 H150 Z" fill="' + T.dark + '"/>' +
      '<path d="M255,342 L146,404" stroke="url(#gold' + u + ')" stroke-width="3" fill="none"/>' +
      '<path d="M255,349 L160,404" stroke="' + T.a1 + '" stroke-width="1" fill="none"/>' +
      '</svg>';
    if (s.showDancer && assets.dancer) h += '<img class="sc-dancer f" alt="" src="' + esc(assets.dancer) + '">';
    h += '<img class="sc-banner" alt="" src="' + esc(assets.banner || BLANK) + '">';
    h += '<div class="sc-slot"></div>';
    if (s.showPhoto) h += '<div class="sc-abs sc-photo" style="border-color:' + T.a1 + '"><img alt="student photo" src="' + esc(assets.photo || BLANK) + '"></div>';
    var nameTop = s.showPhoto ? 239 : 135;
    h += '<div class="sc-abs sc-name" style="top:' + nameTop + 'px">' + esc(String((data && data.name) || '').toUpperCase()) + '</div>';
