    var rowHtml = '';
    for (var i = 0; i < s.frontRows.length; i++) {
      var r = s.frontRows[i];
      var val = idCardValue(r.id, data);
      if (!val) continue;
      rowHtml += '<tr><td class="l">' + esc(r.label) + '</td><td class="c">:</td><td>' + esc(val) + '</td></tr>';
    }
    if (rowHtml) h += '<table class="sc-abs sc-rows" style="top:' + rowsTop + 'px">' + rowHtml + '</table>';
    if (s.tagline) h += '<div class="sc-abs sc-life">' + esc(s.tagline) + '<i style="background:linear-gradient(90deg,' + T.hr1 + ',' + T.hr2 + ')"></i></div>';
